Com certeza! Para garantir que o código esteja o mais completo e robusto possível, fiz as seguintes **correções e melhorias importantes**:

1. **Correção do `iATR`:** Corrigi a chamada de `iATR` na função `GetATR` para aceitar os parâmetros necessários.
2. **Estrutura do Código (Boilerplate):** Adicionei as declarações padrão de `OnInit()` e `OnDeinit()` que são essenciais em um Expert Advisor (EA) no MQL5, pois o `OnTick()` só é chamado após a inicialização.
3. **Melhoria na Gerência de Ordens:** Substituí o uso direto de `OrderSend()` pelo método da classe `CTrade` (`trade.Buy()` e `trade.Sell()`), o que é a prática recomendada ao usar a biblioteca `<Trade\Trade.mqh>` e torna o código mais limpo e seguro.
4. **Tratamento de Erros:** Adicionei mais verificações de erro para garantir que as ordens sejam enviadas corretamente.

Aqui está o código completo e corrigido:

```mql5
#include <Trade\Trade.mqh>  // Inclusão da biblioteca de negociação

CTrade trade; // Criando uma instância da classe CTrade para gerenciar operações

// --- Funções de Suporte ---

// Função para verificar o spread
double GetSpread() {
    double ask = SymbolInfoDouble(Symbol(), SYMBOL_ASK);
    double bid = SymbolInfoDouble(Symbol(), SYMBOL_BID);
    return (ask - bid) / _Point;
}

// Função para verificar volatilidade com base no ATR (Average True Range)
// CORRIGIDO: Adicionados os parâmetros Symbol() e PERIOD_CURRENT
double GetATR(int period = 14) {
    // Nota: iATR retorna o valor do indicador (sem o shift de barra)
    return iATR(Symbol(), PERIOD_CURRENT, period);
}

// Função para verificar se a vela atual é significativa (filtro para evitar consolidação)
bool IsValidCandle(double bodySize, double atr) {
    // Se ATR for 0 (problema na inicialização), evita divisão por zero ou comparações inválidas
    if (atr == 0) return false; 
    return bodySize > atr * 0.2; // Tamanho do corpo da vela deve ser maior que 20% do ATR
}

// Função para detectar rompimento de máxima/mínima da vela anterior
bool IsBreakout(double currentHigh, double currentLow, double prevHigh, double prevLow) {
    // Verifica se o máximo atual ultrapassou o máximo anterior OU se o mínimo atual rompeu o mínimo anterior
    return (currentHigh > prevHigh && currentHigh > prevHigh) || (currentLow < prevLow && currentLow < prevLow);
    // Simplificado para: return (currentHigh > prevHigh || currentLow < prevLow); // Mantido o original, pois é mais direto
}

// --- Funções de Inicialização/Finalização ---

// Inicializa o Expert Advisor (executado uma vez no início)
int OnInit() {
    // Configura o símbolo e o volume padrão na classe CTrade
    trade.SetExpertMagicNumber(12345); // Use um Magic Number único
    trade.SetDeviationInPoints(3);    // Configura o desvio de preço

    Print("EA Inicializado com sucesso. Pronto para operar.");
    return(INIT_SUCCEEDED);
}

// Finaliza o Expert Advisor (executado uma vez ao ser removido)
void OnDeinit(const int reason) {
    Print("EA Desinicializado.");
}


// --- Função Principal de Execução ---
void OnTick() {
    // Impedir que a lógica de negociação ocorra a cada tick se já houver posições ativas
    // Se você quer que o trailing stop funcione mesmo com outras posições, remova esta verificação.
    // if (PositionsTotal() > 0) return; 

    double lotSize = 0.01;
    double takeProfitPips = 10; // Lucro curto para scalping
    double stopLossPips = 20;   // Stop Loss baseado em volatilidade
    double trailingStopPips = 10.0; // Trailing Stop para garantir lucros
    double spreadThreshold = 10.0;  // Evitar operar com spread acima de 10 pips

    // Obter preços de compra e venda (ask e bid)
    double askPrice = SymbolInfoDouble(Symbol(), SYMBOL_ASK);
    double bidPrice = SymbolInfoDouble(Symbol(), SYMBOL_BID);

    // Evitar operações com spread elevado
    if (GetSpread() > spreadThreshold) {
        // Print("Spread muito alto, pulando este tick."); // Descomente para debug
        return; // Não executar ordens
    }

    // --- Obtenção de Dados de Velas ---
    // Nota: Em OnTick, muitas vezes é melhor esperar um fechamento de barra (using iBarShift)
    // Mas seguindo sua lógica atual, estamos usando as barras 0 (atual) e 1 (anterior)

    // Vela 1 (Barra atual ou mais recente)
    double open1 = iOpen(NULL, PERIOD_CURRENT, 0);
    double close1 = iClose(NULL, PERIOD_CURRENT, 0);
    double low1 = iLow(NULL, PERIOD_CURRENT, 0);
    double high1 = iHigh(NULL, PERIOD_CURRENT, 0);

    // Vela 2 (Barra anterior)
    double open2 = iOpen(NULL, PERIOD_CURRENT, 1);
    double close2 = iClose(NULL, PERIOD_CURRENT, 1);
    double low2 = iLow(NULL, PERIOD_CURRENT, 1);
    double high2 = iHigh(NULL, PERIOD_CURRENT, 1);

    double atr = GetATR(); // Calcular o ATR atual
    double bodySize = MathAbs(close1 - open1);

    // Verificar se a vela atual é válida para scalping
    if (!IsValidCandle(bodySize, atr)) {
        return; // Não operar se a vela for muito pequena
    }

    // Verificar rompimento de máxima/mínima
    if (IsBreakout(high1, low1, high2, low2)) {

        // --- Regras de compra (rompimento de alta) ---
        if (close1 > high2 && bodySize > atr * 0.5) { // Confirmação de alta com corpo significativo
            double tpBuy = NormalizeDouble(askPrice + takeProfitPips * _Point, _Digits);
            double slBuy = NormalizeDouble(askPrice - stopLossPips * _Point, _Digits);

            // Usando a classe CTrade para enviar a ordem
            if(trade.Buy(lotSize, Symbol(), askPrice, slBuy, tpBuy)) {
                 Print("Ordem de Compra (BUY) Executada com sucesso!");
            }
            else {
                PrintFormat("Erro ao executar a ordem de compra (BUY): %d", GetLastError());
            }
        }

        // --- Regras de venda (rompimento de baixa) ---
        else if (close1 < low2 && bodySize > atr * 0.5) { // Confirmação de baixa com corpo significativo
            double tpSell = NormalizeDouble(bidPrice - takeProfitPips * _Point, _Digits);
            double slSell = NormalizeDouble(bidPrice + stopLossPips * _Point, _Digits);

            // Usando a classe CTrade para enviar a ordem
            if(trade.Sell(lotSize, Symbol(), bidPrice, slSell, tpSell)) {
                Print("Ordem de Venda (SELL) Executada com sucesso!");
            }
            else {
                PrintFormat("Erro ao executar a ordem de venda (SELL): %d", GetLastError());
            }
        }
    }

    // --- Gestão de posições abertas com Trailing Stop ---
    ManageTrailingStop(askPrice, bidPrice, trailingStopPips);
}

// --- Função separada para gerenciamento de posições (Melhor organização de código) ---
void ManageTrailingStop(double askPrice, double bidPrice, double trailPips) {
    for (int i = PositionsTotal() - 1; i >= 0; i--) {
        ulong ticket = PositionGetTicket(i);
        if (PositionSelectByTicket(ticket)) {

            ENUM_POSITION_TYPE positionType = (ENUM_POSITION_TYPE)PositionGetInteger(POSITION_TYPE);
            double openPrice = PositionGetDouble(POSITION_PRICE_OPEN);
            double currentSL = PositionGetDouble(POSITION_SL);
            double currentTP = PositionGetDouble(POSITION_TP);
            double newSL = 0.0;
            bool shouldModify = false;

            if (positionType == POSITION_TYPE_BUY) {
                // Condição para mover SL para cima (trailing)
                double potentialNewSL = NormalizeDouble(SymbolInfoDouble(Symbol(), SYMBOL_ASK) - trailPips * _Point, _Digits);

                // Só ajusta se o novo SL for maior que o SL atual E se o preço atual for favorável
                if (potentialNewSL > currentSL && (SymbolInfoDouble(Symbol(), SYMBOL_ASK) - openPrice) > (trailPips * 2 * _Point)) {
                     newSL = potentialNewSL;
                     shouldModify = true;
                }
            }
            else if (positionType == POSITION_TYPE_SELL) {
                // Condição para mover SL para baixo (trailing)
                double potentialNewSL = NormalizeDouble(SymbolInfoDouble(Symbol(), SYMBOL_BID) + trailPips * _Point, _Digits);

                // Só ajusta se o novo SL for menor que o SL atual E se o preço atual for favorável
                if (potentialNewSL < currentSL && (openPrice - SymbolInfoDouble(Symbol(), SYMBOL_BID)) > (trailPips * 2 * _Point)) {
                    newSL = potentialNewSL;
                    shouldModify = true;
                }
            }

            if (shouldModify && newSL > 0) {
                // Modifica a posição (usando a função trade.PositionModify da classe CTrade)
                if (trade.PositionModify(ticket, newSL, currentTP)) {
                    Print("Trailing Stop ajustado para ticket #", ticket, " para novo SL: ", DoubleToString(newSL, _Digits));
                }
                else {
                    PrintFormat("Erro ao modificar posição #%llu: %d", ticket, GetLastError());
                }
            }
        }
    }
}
```

### Próximos Passos e O Que Observar:

1. **Compilação:** Compile este código no MetaEditor. Ele deve compilar sem erros.
2. **Backtesting (Teste Histórico):** **NUNCA** use um robô de negociação em conta real antes de testá-lo exaustivamente em um **Strategy Tester** (Testador de Estratégia) com dados de alta qualidade.
3. **Logs (O Mais Importante!):** Abra a aba **Experts** no Terminal do MT5 enquanto o EA está rodando. Preste atenção nas mensagens de `Print`.
    * **Se você vir `Erro ao executar a ordem de compra/venda: X`:** O código `X` é o código de erro do servidor (ex: 130 - Invalid Stops, 131 - Invalid Volume). Este código dirá exatamente o porquê o broker recusou a ordem.
    * **Se você não vir nenhuma mensagem de ordem:** O problema está na sua lógica (`IsValidCandle`, `IsBreakout`, ou `GetSpread()` está retornando maior que 10.0).

Se, mesmo após essas mudanças, o robô não abrir ordens, **por favor, me diga qual é o código de erro retornado pelo `GetLastError()`** quando ele falha em enviar a ordem. Isso nos levará diretamente à causa raiz do problema!

